NAME = 'GerGruenewald: 1924 Grünewaldbibel'
BOOK = 'Song of Solomon'

CHAPTERS = {
    1: {
        1: 'Das Hohe Lied von Salomo. -',
        2: '"An seines Mundes Küssen lasse er mich trinken!" - "Ja lieblicher als Wein ist deine Liebe."',
        3: '"An Wohlgeruch sind deine Öle einzig gut; dein Name selber aber ist das feinste Öl. Drum haben dich die Jungfrauen so lieb." -',
        4: '"Lock mich an dich! Wir wollen eilends kommen." "Der König führe mich in seine Kammern!" "Da wollen jubelnd wir uns deiner freuen, dein Kosen höher preisen als den Wein." "Sie lieben dich mit vollem Recht." -',
        5: '"Ich bin wohl schwarz und dennoch schön, ihr Töchter von Jerusalem, wie Kedars Zelte, wie Salmas Zeltdecken.',
        6: 'Nicht darauf schaut, wie schwarz ich bin, weil mich die Sonne so verbrannt! Die Söhne meiner Mutter zürnten mir und machten mich zur Hüterin von andern Weinbergen. So konnte ich denn meinen eigenen Weinberg nicht behüten." -',
        7: '"Sag mir, du, den ich liebgewonnen! Wo weidest du, wo lagerst du zur Mittagszeit, daß ich nicht als Verdächtige erscheinen muß bei deiner Freunde Herden?" -',
        8: '"Weißt du es nicht, du schönste aller Frauen? Geh den Herden nach, und weide deine Zicklein bei den Hütten ihrer Hirten!',
        9: 'Dich muß ich jetzt vergleichen mit den Stuten vor dem Wagen Pharaos, du, meine Freundin.',
        10: 'Gehänge stünden deinen Wangen lieblich und deinem Halse Schnüre."',
        11: '"Drum wollen wir dir goldene Gehänge machen zu silbernen Zieraten hin."',
        12: '"Bis dorthin, wo der König ruht auf seinem Polster, da würde meine Narde ihren Duft noch senden. -',
        13: 'Ich habe nur ein Myrrhensträußchen, Lieber, das hier an meinem Busen ruht.',
        14: 'Ich habe eine Zyperntraube, Lieber, in den Weinbergen von Engaddi." -',
        15: '"Fürwahr, du bist so schön, du, meine Freundin! Fürwahr, du bist so schön mit deinen Augen, Tauben gleich." -',
        16: '"Fürwahr, du bist so schön, Geliebter, so holdselig! So sei das Grüne unser Lager,',
        17: 'und unsres Hauses Balken seien Zedern, Zypressen unsre Laubengänge!"',
    },
    2: {
        1: '"Ich bin nur wie ein Veilchen auf der Saronsflur, wie eine Lilie der Täler."',
        2: '"Was eine Lilie im Vergleich zur Distel, ist meine Freundin bei den Mädchen." -',
        3: '"Und was ein Apfelbaum ist bei des Waldes Bäumen, das ist mein Liebster bei den Knaben. Mit Lust will ich in seinem Schatten sitzen, und seine Frucht wird meinem Gaumen süß sein.',
        4: 'Er bringt mich jetzt zum Weinhaus hin und richtet über mir der Liebe Flagge auf.',
        5: 'Mit Traubenkuchen stärket mich! Erquicket mich mit Äpfeln! Denn ich bin krank vor Liebe.',
        6: 'Wenn seine Linke unter meinem Haupte wäre und seine Rechte herzte mich!"',
        7: '"Ihr Töchter von Jerusalem, ach, ich beschwöre euch bei den Gazellen oder bei den Hindinnen der Flur: Nicht wecket auf! Nicht stört die Liebe, bis es selber ihr gefällt!"',
        8: '"Horch! Mein Geliebter war soeben angekommen, hinspringend über Berge, über Hügel hüpfend.',
        9: 'Schon glich da einem Reh mein Liebster oder einem jungen Hirsch. Er stellt sich hinter unsere Mauer und späht durchs Fenster, blickt durchs Gitter.',
        10: "Dann hob mein Liebster an und sprach zu mir: 'Auf, meine Freundin! Du, meine Schöne, komm!",
        11: 'Vorüber ist die Winterzeit; der Regen ist vorbei.',
        12: 'Die Blumen zeigen sich auf Erden, und der Gesänge Zeit ist da. Der Turteltaube Ruf, der läßt in unserm Land sich hören.',
        13: 'Schon reifen an dem Feigenbaum die Früchte; Duft haucht die Rebenblüte aus. Auf, meine Freundin! Du, meine Schöne, komm!',
        14: "Du meine Taube in den Felsenspalten, in dem Versteck der Klüfte! Laß deinen Anblick mich genießen! Laß deine Stimme mich vernehmen! Denn deine Stimme ist so süß, dein Anblick lieblich.'",
        15: 'Die Füchse fanget uns, die kleinen Füchse, die die Weinberge verderben! Denn jetzt schon tragen reife Beeren unsere Weinberge.',
        16: 'Ja, mein soll mein Geliebter werden wie ich sein. Bei Lilien soll er weiden,',
        17: 'bis daß der Tag schon luftig wird und bis die Schatten fliehen! Dann streife, du Geliebter, abermals, dem Reh vergleichbar oder einem jungen Hirsch, umher auf klüftereichen Bergen!"',
    },
    3: {
        1: '"Ich sehnte mich auf meinem Lager eines Nachts nach dem, den meine Seele liebt. Ich sehnte mich nach ihm und fand ihn nicht.',
        2: 'So will ich aufstehen, die Stadt durchstreifen, auf Märkten und auf Straßen suchen ihn, den meine Seele liebt. Ich suchte ihn und fand ihn nicht.',
        3: "Da trafen mich die Wächter, die in der Stadt umgehen: 'Habt ihr ihn wohl gesehen, den meine Seele liebt?'",
        4: 'An ihnen kaum vorüber, fand ich den, den meine Seele liebt. Ich halte ihn nun fest und will von ihm nicht lassen, bis daß ich ihn in meiner Mutter Haus gebracht, hin zu der Kammer jener Frau, die mich geboren.',
        5: "'Ihr Töchter von Jerusalem!' so rufe ich. 'Ach, ich beschwöre euch bei den Gazellen oder bei den Hindinnen der Fluren: Weckt nicht auf! Stört nicht die Liebe, bis es selber ihr gefällt!'",
        6: 'Was ist\'s, was dort heraufkommt aus der Wüste, Rauchessäulen gleich, im Duft von Myrrhen und von Weihrauch, von Spezereien aller Art?"',
        7: '"Fürwahr, das ist die Sänfte Salomos, um sie herum der Helden sechzig, genommen aus den Helden Israels.',
        8: 'Sie alle kriegstüchtig, im Kampf erprobt, jedweder mit dem Schwert an seiner Hüfte, um der Gefahr zur Nachtzeit willen."',
        9: '"Der König Salomo, der ließ sich einen Tragstuhl fertigen aus Holz vom Libanon.',
        10: 'Aus Silber ließ er seine Säulen machen, aus Gold die Lehne, seinen Sitz aus Purpurzeug. Sein Innres ist bedeckt mit Bildern aus dem Liebesleben der Töchter von Jerusalem.',
        11: 'Wohlan, ihr Sionstöchter! So weidet euch am Anblicke des Königs Salomo, am Kranz, den seine Mutter ihm gewunden an seinem Hochzeitstag, am Tage seiner Herzensfreude!"',
    },
    4: {
        1: '"Du bist so schön, du, meine Freundin, so schön, und deine Augen sind wie Täubchen, und hinter deinem Schleier gleicht dein Haar wohl einer Ziegenherde, die sich herab am Gileadberge lagert.',
        2: 'Und deine Zähne gleichen einer Herde, die sich zur Schur bereithält, die aus der Schwemme steigt, die allesamt Zwillinge trägt, und deren keines ohne Junges ist.',
        3: 'Und deine Lippen gleichen einem Scharlachfaden, und lieblich ist dein Mund, und deine Schläfe schimmert hinterm Schleier vor gleichwie die Scheibe des Granatapfels.',
        4: 'Dein Hals gleicht Davids Turm, mit Zinnen wohlbewehrt, und tausend Schilde hängen dran, sie alle Heldenschilde.',
        5: 'Dein Busen gleicht zwei Rehkälbchen, Gazellenzwillingen, die in den Lilien weiden."',
        6: '"So lange, bis der Tag ganz luftig wird und bis die Schatten fliehen, will ich zu diesem Myrrhenberg hingehen, zu diesem Weihrauchhügel."',
        7: '"An dir ist alles schön, du, meine Freundin, und kein Makel ist an dir.',
        8: 'Du brächtest mich vom Libanon, du meine Braut, ja von dem Libanon zurück. Du führtest mich zurück vom Gipfel des Amana, vom Gipfel des Sanir und Hermon, von Löwenwohnungen sogar, von Pantherbergen her.',
        9: 'Du hast mich des Verstands beraubt, du, meine Schwester, meine Braut. Du hast mich des Verstands beraubt, allein durch einen einzigen Blick, durch eine einzige Wendung deines Halses.',
        10: 'Wie süß ist deine Liebe, meine Schwester, meine Braut! Um wieviel köstlicher denn Wein ist deine Liebe und deiner Öle Duft als alle Wohlgerüche!',
        11: 'Es träufeln deine Lippen, Braut, von Honigseim, und deine Zunge, sie birgt Milch und Honig; dem Duft des Libanon gleicht deiner Kleider Duft.',
        12: 'Ein Garten, der verschlossen, ist meine Schwester Braut, ein Born, verschlossen; ein Quell, versiegelt.',
        13: 'Dein Schoß ist ein Granatenhain mit Früchten, wunderköstlich, mit Zyperntrauben, Narden.',
        14: 'Ja, Narde, Safran, Kalmus, Zimt mit allerlei Weihrauchgehölz und Myrrhen, Aloë, mit allerlei Balsamessenzen.',
        15: 'Ein Brunnen mit lebendigem Wasser und Bäche, die vom Libanon herniederrieseln, sind meine Gartenquelle."',
        16: '"Erwache, Nord! Komm, Süd! Durchwehe meinen Garten, daß sein Balsamduft hinströme! - In seinen Garten komme mein Geliebter, genieße seine Früchte, die so köstlich!"',
    },
    5: {
        1: '"So komme ich in meinen Garten, du, meine Schwester Braut. Ich pflücke meine Myrrhe samt dem Balsam. Ich esse meine Wabe samt dem Honig. Ich trinke meinen Wein mitsamt der Milch. Ihr Freunde, jetzt sollt ihr zu essen haben und viel zu trinken, ihr Vertrauten!"',
        2: '"Ich schlief; jedoch mein Herz war wach. Da horch! Mein Liebster klopft!""Du, meine Schwester, meine Freundin, öffne mir! Du meine Taube, meine Reine! Mein Haupt ist voller Tau und meine Locken voller Tropfen dieser Nacht."',
        3: '"Ich habe mein Gewand schon abgelegt. Wie sollte ich es wieder anziehn? Auch meine Füße schon gewaschen, wie soll ich nochmals sie beschmutzen?" -',
        4: 'Da zog mein Liebster seine Hand zurück vom Eingang; nun wallte auf in mir mein Herz.',
        5: 'Ich stand jetzt auf, um meinen Liebsten einzulassen. Da wurden meine Hände feucht von Myrrhe, die auf des Riegels Griffe lag.',
        6: 'Ich mache meinem Liebsten auf; doch mein Geliebter war entwichen und blieb verschwunden. Mein Leben hätte ich gegeben um ein Wort von ihm; ich suchte ihn und fand ihn nicht. Ich rief ihn an; er gab mir keine Antwort mehr.',
        7: 'Da fanden mich die Wächter, die in der Stadt umgehen. Sie schlugen mich und machten Wunden mir; es rissen mir den Schleier weg die Wächter unserer Stadtmauern. -',
        8: '"Ihr Töchter von Jerusalem! Ach, ich beschwöre euch, wenn je ihr meinen Liebsten finden solltet, daß ihr ihm alsdann sagt, ich sei vor Liebe krank." -',
        9: '"Was ist dein Liebster als Geliebter, du schönste aller Frauen? Was ist dein Liebster als Geliebter, daß du uns so beschwörst?" -',
        10: '"Mein Liebster, er ist blendend weiß und rot, aus Tausenden hervorragend.',
        11: 'Sein Haupt von Gold und seiner Locken eine große Menge, schwarz wie Rabenfedern.',
        12: 'Und seine Augen gleichen Tauben an den Wasserbächen, milchweiß gewaschen, dasitzend in Behaglichkeit.',
        13: 'Und seine Wangen sind wie Balsambeete und Schreine voll von Wohlgerüchen, und seine Lippen sind wie rote Lilien, von feiner Myrrhe überfließend.',
        14: 'Und seine Arme sind wie goldne Walzen, mit Tarsissteinen eingefaßt, sein Leib ein Werk aus Elfenbein, bedeckt mit Saphirstein.',
        15: 'Und seine Beine gleichen Marmorsäulen, gestützt auf Feingoldfüße. Sein Anblick ist wie der des Libanon, großartig wie die Zedern.',
        16: 'Sein Gaumen ist ganz Süßigkeit, und er ganz Lieblichkeit. So ist mein Liebster, so mein Freund, ihr Töchter von Jerusalem."',
    },
    6: {
        1: '"Wohin pflegt dein Geliebter sonst zu gehen, schönste aller Frauen? Wohin pflegt dein Geliebter sich zu wenden, daß wir ihn mit dir suchen?"',
        2: '"Mein Liebster pflegt zu gehn in seinen Garten, zu den Balsambeeten, sich recht an meinem Garten zu erlaben und Lilien zu pflücken.',
        3: 'Ach, ich gehöre meinem Liebsten. Mein Liebster, er ist mein, der in den Lilien weiden soll." -',
        4: '"Du bist so schön, du, meine Freundin, gerade so wie Tirsa, so lieblich wie Jerusalem und dennoch schrecklich wie die Löwen.',
        5: 'Wend deine Augen ab von mir! Sie setzen mich in Flammen. Dein Haar gleicht einer Ziegenherde, die an dem Gilead herab sich lagert,',
        6: 'und deine Zähne sind wie eine Herde Mutterschafe, die aus der Schwemme steigt, die allesamt Zwillinge tragen, und deren keines ohne Junges ist.',
        7: 'Und deine Wange hinter deinem Schleier gleicht der Scheibe des Granatapfels.',
        8: "Sind's auch der Königinnen sechzig und achtzig Nebenfrauen und Jungfraun ohne Zahl,",
        9: 'so ist nur eine meine Taube, meine Reine, die Lieblingstochter ihrer Mutter, die kindlich der, die sie gebar, ergeben ist. Die Mädchen sehen sie und preisen sie. Die Königinnen und die Nebenfrauen müssen, sie bewundernd, sprechen:',
        10: '\'Wer ist\'s, die da herabblickt wie die Morgenröte, schön wie der Mond, rein wie die Sonne, und dennoch schrecklich wie die Löwen?\'" -',
        11: '"Zum Nußgarten wollt\' ich hinab, mich an der Palmen frischen Trieben zu erfreun, zu sehen, ob der Weinstock sproßt, ob die Granaten blühen.',
        12: 'Da haben gänzlich unvermutet Wagen eines fürstlichen Gefolges in Verwirrung mich gebracht."',
    },
    7: {
        1: '"Sulamith! Du! Halt, Halt! Daß wir dich anschaun können, halt! Halt!" "Wozu begaffet ihr die Sulamith wie eine öffentliche Tänzerin?" -',
        2: '"Wie schön doch wären deine Füße in Sandalen, du Prinzessin! Es gleicht die Wölbung deiner Hüften einem Schmuck, dem Werk von Künstlerhänden.',
        3: 'Dein Schoß ist ein gerundet Becken, dem Mischwein nimmer fehlen darf, dein Leib ein Weizenhaufen, von Lilien umsäumt.',
        4: 'Dein Busen gleicht zwei Rehkälbchen, Gazellenzwillingen.',
        5: 'Dein Hals ist wie ein Elefantenturm, und deine Augen wie die Teiche dort zu Hesbon an dem Tor der Völkerreichen, und deine Nase gleicht dem Turme auf dem Libanon, der nach Damaskus schaut.',
        6: 'Dem Karmel gleicht dein Haupt auf dir, und deines Hauptes Haar sind Purpurlocken, in Gitterwerk gebunden.',
        7: 'Wie schön mußt du dann sein, wie lieblich, wenn vollends Liebe sich mit diesen Wonnen eint!',
        8: 'Dein Wuchs ist so, daß er der Palme gleicht; den Trauben gleicht dein Busen.',
        9: 'Drum nehme ich mir vor, die Palme zu ersteigen und ihre Früchtezweige zu ergreifen. Dein Busen gleicht den Trauben an dem Weinstock und deiner Nase Duft den Äpfeln,',
        10: 'dem besten Wein dein Gaumen, der glatt in meinen Becher fließen soll, einschläfernd über meine Lippen gleiten!" -',
        11: '"Ich aber bin zu eigen meinem Liebsten, und ihm mich hinzugeben, ist mir Pflicht.',
        12: 'Nun komm, Geliebter! Wir wollen auf das Feld hinaus und unter Zyperntrauben uns verweilen.',
        13: 'Wir gehen zu den Weinbergen in aller Früh und sehen, ob der Weinstock sproßt und ob sich seine Beeren bilden, ob die Granaten blühen. Dort möchte ich dir meine Liebe schenken. Dort spenden Liebesäpfel ihren Duft. Dort sind vor unserer Türe Früchte, köstlich, mannigfaltig. Ganz frische, samt den alten habe ich dir dort, Geliebter, aufbewahrt."',
    },
    8: {
        1: '"Ach, daß du mir doch Bruder wärst, den meiner Mutter Brust gesäugt Bin ich mit dir im Freien, möchte ich dich küssen. Ich würde darum nicht verachtet.',
        2: 'Jetzt führe ich dich hin, geleite dich zu meiner Mutter Haus, die mich erzogen. Ich gebe dir gewürzten Wein zu trinken, Granatenmost.',
        3: 'Alsdann sei seine Linke unter meinem Haupt, und seine Rechte herze mich!',
        4: 'Ihr Töchter von Jerusalem! Ach, ich beschwör euch: Weckt nicht auf! Stört nicht die Liebe, bis ihr\'s selbst gefällt!" -',
        5: '"Wer ist\'s, der dort heraufkommt aus der Wüste, gestützt auf ihren Liebsten?" - "Ich hab dich einen Apfelbaum genannt. Daran hat deine Mutter dich gebunden, daran gebunden, die das Dasein dir geschenkt." -',
        6: '"So drücke mich gleich einem Siegel auf dein Herz, auf deinen Arm gleich einem Siegel!" "Stark wie der Tod, so ist die Liebe, fest wie die Unterwelt die Liebesleidenschaft und ihre Flammengluten, Feuergluten.',
        7: 'Viel Wasser können nicht die Liebe löschen, und Ströme sie nicht überfluten. Wenn einer alle Habe seines Hauses für die Liebe gäbe, man würde ihn doch bloß verachten." -',
        8: '"Wir haben eine kleine Schwester, noch ohne Busen. Was machen wir mit unsrer Schwester an dem Tage, da man um sie freit?',
        9: 'Wenn sie dann einer Mauer gleicht, errichten wir ein silbern Pfahlwerk um sie her. Ist sie dagegen eine Tür, dann wollen wir durch Zedernbohlen sie verwahren."',
        10: '"Nun bin ich eine Mauer, und Türmen gleicht mein Busen. In seinen Augen freilich bin ich einer gleich, die schon vollzogen hat die Übergabe."',
        11: '"Zu Baal Hamon war Salomo ein Weinberg eigen. Er hat den Weinberg Hütern übergeben, von denen jeder seine Frucht abliefern mußte im Wert von tausend Silberlingen."',
        12: '"Mit meinem Weinberg, der mein eigen, ist\'s nach meiner Ansicht ebenso: Die tausend, Salomo, gehören dir; zweihundert dann den Hütern seiner Früchte."',
        13: '"Die du in Gärten wohnst, auf deine Stimme lauschen die Gefährten. Laß mich sie hören!" -',
        14: '"Mein Liebster, flieh, dem Reh gleich oder jungen Hirschen, auf die Balsamberge!"',
    },
}
